#!/usr/bin/env bash
# Generates book/src/configure/variables.md from the assignments of the configure files.
# Usage: bash book/scripts/gen-config-vars.bash [OUTPUT_FILE]
set -euo pipefail

top="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
output="${1:-${top}/book/src/configure/variables.md}"
files=(RELEASE CONFIG_SITE CONFIG_EPICSENV CONFIG_SYSTEMD CONFIG_VARS CONFIG_SQL CONFIG_TOMCAT CONFIG_SRC)

{
    cat <<'HEADER'
# Configuration variables and their defaults

<!-- Generated by book/scripts/gen-config-vars.bash from configure/*. Do not edit. -->

This page lists every variable that the files under `configure/` assign, with the operator, the value that the file assigns and the comment written above it. A value is shown as written: `$(NAME)` and `${NAME}` refer to another variable and are expanded by Make when the variable is used. `make -s print-<variable_name>` prints the value that is in effect.

An assignment with `:=` is evaluated once, where it is written. An assignment with `=` is evaluated each time the variable is used. An assignment with `?=` applies only when the variable has no value yet. A local file that `CONFIG_SITE`, `CONFIG_VARS` or `RELEASE` includes can replace any of them.

HEADER
    for file in "${files[@]}"; do
        awk -v file="${file}" '
            function clean(s) { gsub(/^#+[ \t]*/, "", s); gsub(/[ \t]+$/, "", s); return s }
            function esc(s) { gsub(/\|/, "\\|", s); return s }
            BEGIN { n = 0; comment = "" }
            /^[ \t]*$/ { comment = ""; next }
            /^[ \t]*#/ {
                text = clean($0)
                if (text != "" && text !~ /^[A-Za-z_][A-Za-z0-9_]*[ \t]*(:=|\?=|=)/) {
                    comment = (comment == "" ? text : comment " " text)
                }
                next
            }
            /^[A-Za-z_][A-Za-z0-9_]*[ \t]*(:=|\?=|\+=|=)/ {
                match($0, /^[A-Za-z_][A-Za-z0-9_]*/)
                name = substr($0, RSTART, RLENGTH)
                rest = substr($0, RLENGTH + 1)
                sub(/^[ \t]*/, "", rest)
                match(rest, /^(:=|\?=|\+=|=)/)
                op = substr(rest, RSTART, RLENGTH)
                value = substr(rest, RLENGTH + 1)
                sub(/^[ \t]*/, "", value)
                gsub(/[ \t]+$/, "", value)
                if (length(comment) > 420) { comment = substr(comment, 1, 417) "..." }
                rows[n++] = "| `" name "` | `" op "` | `" esc(value == "" ? "(empty)" : value) "` | " esc(comment) " |"
                comment = ""
                next
            }
            { comment = "" }
            END {
                if (n > 0) {
                    printf "## Variables set in configure/%s\n\n", file
                    print "| Variable | Operator | Value as written | Comment above it |"
                    print "| :--- | :--- | :--- | :--- |"
                    for (i = 0; i < n; i++) print rows[i]
                    print ""
                }
            }
        ' "${top}/configure/${file}"
    done
} > "${output}"
printf 'wrote %s (%s lines)\n' "${output}" "$(wc -l < "${output}")"
